// ---- src/text.js ----
/** Text helpers: HTML stripping, quoted-history removal, masking and redaction. Pure functions, no dependencies. */

function stripHtml(html) {
  return String(html || '')
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
}

/** Keep only what the person actually wrote: drop quoted history, forwarded headers, and mobile signatures. */
function cleanReply(text) {
  let t = '\n' + String(text || '').replace(/\r\n/g, '\n');
  const cutters = [
    /\n\s*On [^\n]{0,200}(?:\n[^\n]{0,120})?\bwrote:/i,
    /\n\s*-{2,}\s*(?:Original Message|Forwarded message)/i,
    /\n\s*_{5,}/,
    /\n\s*From:\s[^\n]+\n\s*(?:Sent|Date):/i,
    /\n\s*Sent from my /i,
    /\n\s*Get Outlook for /i,
  ];
  for (const re of cutters) {
    const m = re.exec(t);
    if (m) t = t.slice(0, m.index);
  }
  return t
    .split('\n')
    .filter((line) => !/^\s*>/.test(line))
    .join('\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

function maskEmail(email) {
  const s = String(email || '');
  const at = s.indexOf('@');
  if (at < 1) return s ? '***' : '';
  return `${s[0]}***${s.slice(at)}`;
}

/** Mask every email address inside free text (used for Slack excerpts). */
function maskEmailsInText(text) {
  return String(text || '').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, (m) => maskEmail(m));
}

function truncate(text, max) {
  const s = String(text || '');
  return s.length > max ? `${s.slice(0, max - 1).trimEnd()}…` : s;
}

/** Remove contact details before text is sent to any third-party service (LLM fallback). */
function redactForLlm(text) {
  return String(text || '')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/https?:\/\/\S+/gi, '[url]')
    .replace(/(?:\+?\d[\d\s().-]{7,}\d)/g, '[phone]');
}

/** Small, dependency-free string hash (djb2) used to build fallback reply IDs. */
function hashString(str) {
  let h = 5381;
  const s = String(str);
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return h.toString(16).padStart(8, '0');
}

// ---- src/config.js ----
/**
 * Central configuration loader (environment variables -> one validated object).
 *
 * SANDBOX_MODE defaults to TRUE and is fail-safe: only an explicit false/0/no/off disables it, so a typo
 * keeps the dry-run gate closed. Secrets (webhook URLs, API tokens) are NEVER copied into this object -
 * only booleans like `slackConfigured` - so they do not end up in n8n execution data.
 */

const ENV_KEYS = [
  'SANDBOX_MODE',
  'CONFIDENCE_THRESHOLD',
  'UNSUBSCRIBE_CONFIDENCE_THRESHOLD',
  'ENABLE_LLM_FALLBACK',
  'LLM_MAX_CONFIDENCE',
  'LLM_MODEL',
  'DATE_FORMAT_PREFERENCE',
  'OOO_DEFAULT_PAUSE_DAYS',
  'OOO_REENROLL_DELAY_DAYS',
  'NOT_NOW_FOLLOWUP_DAYS',
  'INTERESTED_TASK_DUE_HOURS',
  'SEQUENCE_PROVIDER',
  'APOLLO_STOP_MODE',
  'HUBSPOT_ENABLED',
  'OWN_EMAIL_DOMAINS',
  'OWNER_SLACK_MAP_JSON',
  'NOTIFY_ON_UNSUBSCRIBE',
  'NOTIFY_ON_NOT_NOW',
  'PAUSE_ON_REVIEW',
  'REVIEW_CREATE_TASK',
  'SLACK_INCLUDE_EXCERPT',
  'ENABLE_LOCAL_RESUME_QUEUE',
  'MAX_BODY_CHARS',
  // presence-only (the URL itself is read by the HTTP node, never stored in cfg):
  'SLACK_WEBHOOK_URL',
  'SUPPRESSION_WEBHOOK_URL',
  'SEQUENCE_WEBHOOK_URL',
  'LLM_API_URL',
];

/** Copy known keys from an env-like object. If n8n blocks env access, reads throw: stop and use safe defaults. */
function readEnv(source) {
  const env = {};
  for (const key of ENV_KEYS) {
    try {
      const v = source[key];
      if (v !== undefined && v !== null && v !== '') env[key] = v;
    } catch (e) {
      break;
    }
  }
  return env;
}

const present = (v) => v !== undefined && v !== null && String(v).trim() !== '';

function toBool(value, fallback) {
  if (!present(value)) return fallback;
  return ['true', '1', 'yes', 'on'].includes(String(value).trim().toLowerCase());
}

/** Fail-safe: ON unless the value is an explicit off word. */
function toSandbox(value) {
  if (!present(value)) return true;
  return !['false', '0', 'no', 'off'].includes(String(value).trim().toLowerCase());
}

function toNum(value, fallback, name) {
  if (!present(value)) return fallback;
  const n = Number(value);
  if (!Number.isFinite(n)) throw new Error(`${name} must be a number, got "${value}"`);
  return n;
}

function toList(value) {
  return present(value) ? String(value).split(',').map((s) => s.trim().toLowerCase().replace(/^@/, '')).filter(Boolean) : [];
}

function toEnum(value, allowed, fallback, name) {
  if (!present(value)) return fallback;
  const v = String(value).trim().toLowerCase();
  if (!allowed.includes(v)) throw new Error(`${name} must be one of: ${allowed.join(', ')} (got "${value}")`);
  return v;
}

function parseJsonMap(value, name) {
  if (!present(value)) return {};
  try {
    const parsed = typeof value === 'string' ? JSON.parse(value) : value;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('must be a JSON object');
    return parsed;
  } catch (e) {
    throw new Error(`${name} is not a valid JSON object: ${e.message}`);
  }
}

function loadConfig(env) {
  const e = env || {};
  const cfg = {
    sandbox: toSandbox(e.SANDBOX_MODE),
    confidenceThreshold: toNum(e.CONFIDENCE_THRESHOLD, 0.8, 'CONFIDENCE_THRESHOLD'),
    unsubscribeThreshold: toNum(e.UNSUBSCRIBE_CONFIDENCE_THRESHOLD, 0.6, 'UNSUBSCRIBE_CONFIDENCE_THRESHOLD'),
    enableLlmFallback: toBool(e.ENABLE_LLM_FALLBACK, false),
    llmMaxConfidence: toNum(e.LLM_MAX_CONFIDENCE, 0.9, 'LLM_MAX_CONFIDENCE'),
    llmModel: present(e.LLM_MODEL) ? String(e.LLM_MODEL) : 'your-model-name',
    dateFormat: toEnum(e.DATE_FORMAT_PREFERENCE, ['mdy', 'dmy'], 'mdy', 'DATE_FORMAT_PREFERENCE').toUpperCase(),
    oooDefaultPauseDays: toNum(e.OOO_DEFAULT_PAUSE_DAYS, 7, 'OOO_DEFAULT_PAUSE_DAYS'),
    oooReenrollDelayDays: toNum(e.OOO_REENROLL_DELAY_DAYS, 1, 'OOO_REENROLL_DELAY_DAYS'),
    notNowFollowupDays: toNum(e.NOT_NOW_FOLLOWUP_DAYS, 90, 'NOT_NOW_FOLLOWUP_DAYS'),
    interestedTaskDueHours: toNum(e.INTERESTED_TASK_DUE_HOURS, 4, 'INTERESTED_TASK_DUE_HOURS'),
    sequenceProvider: toEnum(e.SEQUENCE_PROVIDER, ['none', 'apollo', 'webhook'], 'none', 'SEQUENCE_PROVIDER'),
    apolloStopMode: toEnum(e.APOLLO_STOP_MODE, ['stop', 'remove'], 'stop', 'APOLLO_STOP_MODE'),
    hubspotEnabled: toBool(e.HUBSPOT_ENABLED, false),
    ownDomains: toList(e.OWN_EMAIL_DOMAINS),
    ownerSlackMap: parseJsonMap(e.OWNER_SLACK_MAP_JSON, 'OWNER_SLACK_MAP_JSON'),
    notifyOnUnsubscribe: toBool(e.NOTIFY_ON_UNSUBSCRIBE, false),
    notifyOnNotNow: toBool(e.NOTIFY_ON_NOT_NOW, false),
    pauseOnReview: toBool(e.PAUSE_ON_REVIEW, true),
    reviewCreateTask: toBool(e.REVIEW_CREATE_TASK, true),
    slackIncludeExcerpt: toBool(e.SLACK_INCLUDE_EXCERPT, true),
    enableLocalResumeQueue: toBool(e.ENABLE_LOCAL_RESUME_QUEUE, true),
    maxBodyChars: toNum(e.MAX_BODY_CHARS, 20000, 'MAX_BODY_CHARS'),
    slackConfigured: present(e.SLACK_WEBHOOK_URL),
    suppressionWebhookConfigured: present(e.SUPPRESSION_WEBHOOK_URL),
    sequenceWebhookConfigured: present(e.SEQUENCE_WEBHOOK_URL),
    llmConfigured: present(e.LLM_API_URL),
  };

  for (const [name, v] of [['CONFIDENCE_THRESHOLD', cfg.confidenceThreshold], ['UNSUBSCRIBE_CONFIDENCE_THRESHOLD', cfg.unsubscribeThreshold], ['LLM_MAX_CONFIDENCE', cfg.llmMaxConfidence]]) {
    if (!(v > 0 && v <= 1)) throw new Error(`${name} must be between 0 (exclusive) and 1`);
  }
  for (const [name, v] of [['OOO_DEFAULT_PAUSE_DAYS', cfg.oooDefaultPauseDays], ['NOT_NOW_FOLLOWUP_DAYS', cfg.notNowFollowupDays], ['MAX_BODY_CHARS', cfg.maxBodyChars]]) {
    if (!(v > 0)) throw new Error(`${name} must be greater than 0`);
  }
  if (cfg.enableLlmFallback && !cfg.llmConfigured) {
    throw new Error('ENABLE_LLM_FALLBACK=true requires LLM_API_URL (an OpenAI-compatible chat-completions endpoint)');
  }
  return cfg;
}

// ---- src/normalize.js ----
/**
 * Turns an incoming webhook body into one normalized reply object.
 * Accepts a documented generic schema plus tolerant aliases for Apollo- and HubSpot-style payloads.
 * Adapters are best-effort: always confirm field names against what YOUR tool actually sends
 * (use the generic schema in schemas/reply-payload.schema.json if they differ).
 */


const getPath = (obj, path) => path.split('.').reduce((acc, key) => (acc === undefined || acc === null ? undefined : acc[key]), obj);

function pick(obj, paths) {
  for (const p of paths) {
    const v = getPath(obj, p);
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

/** "Jane Doe <jane@example.com>" or "jane@example.com" -> { email, name } */
function parseAddress(value) {
  const s = String(value || '').trim();
  const m = /^(.*?)<([^>]+)>$/.exec(s);
  if (m) return { name: m[1].replace(/^["'\s]+|["'\s]+$/g, ''), email: m[2].trim().toLowerCase() };
  return { name: '', email: s.toLowerCase() };
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const numericId = (v) => (/^\d+$/.test(String(v).trim()) ? String(v).trim() : '');

function normalizePayload(body, headers, opts) {
  const o = Object.assign({ maxBodyChars: 20000, nowMs: Date.now() }, opts);
  const b = body && typeof body === 'object' ? body : {};
  const h = {};
  Object.keys(headers || {}).forEach((k) => { h[k.toLowerCase()] = headers[k]; });

  const source = String(pick(b, ['source']) || h['x-reply-source'] || 'generic').toLowerCase();

  let from = { email: '', name: '' };
  if (b.from && typeof b.from === 'object') from = { email: String(b.from.email || '').trim().toLowerCase(), name: String(b.from.name || '') };
  else if (typeof b.from === 'string') from = parseAddress(b.from);
  else from = { email: String(pick(b, ['fromEmail', 'from_email', 'sender_email', 'sender', 'email', 'contact.email'])).trim().toLowerCase(), name: String(pick(b, ['fromName', 'from_name'])) };
  if (!EMAIL_RE.test(from.email)) throw new Error('Payload needs a valid sender email (from.email / fromEmail / email)');

  const html = String(pick(b, ['html', 'body_html', 'reply_html']));
  const text = String(pick(b, ['body', 'text', 'plain', 'reply_text', 'reply_body', 'message', 'content']));
  if (!text.trim() && !html.trim()) throw new Error('Payload needs a reply body (body / text / reply_text / html)');

  const receivedRaw = pick(b, ['receivedAt', 'received_at', 'timestamp', 'date', 'created_at']);
  const receivedMs = receivedRaw ? Date.parse(receivedRaw) : NaN;
  const receivedAt = new Date(Number.isFinite(receivedMs) ? receivedMs : o.nowMs).toISOString();

  const subject = String(pick(b, ['subject', 'email_subject']));
  const hubspotRaw = pick(b, ['contact.hubspotContactId', 'hubspotContactId', 'hubspot_contact_id', source === 'hubspot' ? 'contactId' : 'hs_contact_id', 'hs_object_id', 'objectId']);

  const reply = {
    source,
    receivedAt,
    from,
    subject,
    body: text.slice(0, o.maxBodyChars),
    html: text.trim() ? '' : html.slice(0, o.maxBodyChars),
    headers: b.headers && typeof b.headers === 'object' ? b.headers : {},
    contact: {
      email: String(pick(b, ['contact.email', 'contactEmail']) || from.email).toLowerCase(),
      hubspotContactId: numericId(hubspotRaw),
      apolloContactId: String(pick(b, ['contact.apolloContactId', 'apolloContactId', 'apollo_contact_id', source === 'apollo' ? 'contact_id' : 'apollo_id'])),
    },
    sequence: {
      id: String(pick(b, ['sequence.id', 'sequenceId', 'sequence_id'])),
      name: String(pick(b, ['sequence.name', 'sequenceName', 'sequence_name'])),
      apolloSequenceId: String(pick(b, ['sequence.apolloSequenceId', 'apolloSequenceId', 'apollo_sequence_id', 'emailer_campaign_id'])),
    },
  };
  reply.replyId = String(pick(b, ['replyId', 'reply_id', 'id', 'message_id', 'messageId']) || `r_${hashString(`${from.email}|${subject}|${receivedAt}|${(text || html).slice(0, 200)}`)}`);
  return reply;
}

// ---- node logic (scripts/node-code/wf1-intake.js) ----
// Code node: "Load Config & Normalize" (Run Once for All Items)
// Loads settings, validates + normalizes the incoming webhook body, and de-duplicates replies by replyId.
// If your n8n blocks $env access, hard-code settings here instead, e.g. { SANDBOX_MODE: 'true' }.
const OVERRIDES = {};

const env = Object.assign(readEnv($env), OVERRIDES);
const cfg = loadConfig(env);
const req = $input.first().json;
const nowMs = Date.now();
const reply = normalizePayload(req.body, req.headers, { maxBodyChars: cfg.maxBodyChars, nowMs });

// Idempotency: providers retry webhooks. Sandbox runs never record anything.
const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};
Object.keys(state.processed).forEach((k) => { if (state.processed[k] < nowMs - 14 * 86400000) delete state.processed[k]; });
const duplicate = Boolean(state.processed[reply.replyId]);
if (!duplicate && !cfg.sandbox) state.processed[reply.replyId] = nowMs;

return [{ json: { cfg, reply, duplicate, sandbox: cfg.sandbox } }];

