    label = 'UNSUBSCRIBE';
    confidence = scores.UNSUBSCRIBE;
  } else {
    const ranked = LABELS.map((l) => ({ l, s: scores[l] })).sort((a, b) => b.s - a.s);
    const top = ranked[0];
    const second = ranked[1];
    if (top.s > 0) {
