  while ((m = dayMonth.exec(text))) {
    const day = Number(m[1]);
    push(m[3] ? isoDate(Number(m[3]), monthNum(m[2]), day) : inferYear(monthNum(m[2]), day, refMs), m.index);
  }

  const numeric = /\b(\d{1,2})[/.](\d{1,2})[/.](20\d{2}|\d{2})\b/g;
  while ((m = numeric.exec(text))) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const y = fullYear(m[3]);
    let month = dateFormat === 'DMY' ? b : a;
    let day = dateFormat === 'DMY' ? a : b;
    if (month > 12 && day <= 12) [month, day] = [day, month]; // unambiguous: swap
    push(isoDate(y, month, day), m.index);
  }

  const weekday = new RegExp(`\\b(?:back|return(?:ing)?|in\\s+the\\s+office|available)\\s+(?:on\\s+)?(?:next\\s+)?(${WEEKDAYS})\\b`, 'gi');
  while ((m = weekday.exec(text))) {
    const target = WEEKDAY_INDEX[m[1].toLowerCase()];
    const refDow = new Date(refMs).getUTCDay();
    const delta = ((target - refDow + 7) % 7) || 7;
    push(new Date(Date.UTC(new Date(refMs).getUTCFullYear(), new Date(refMs).getUTCMonth(), new Date(refMs).getUTCDate() + delta)).toISOString().slice(0, 10), m.index);
  }
  return found.sort((x, y) => x.index - y.index);
}

/**
 * @returns {{ returnDate: string, basis: string } | null}  returnDate = first day the person is back (YYYY-MM-DD)
 */
function parseReturnDate(text, refMs, dateFormat) {
  const dates = collectDates(String(text || ''), refMs, dateFormat === 'DMY' ? 'DMY' : 'MDY');
  if (!dates.length) return null;

  const keywords = [];
  const kw = /\b(return(?:ing|s)?|back|until|till|through|thru|resum(?:e|ing)|available\s+again)\b/gi;
  let m;
  while ((m = kw.exec(text))) keywords.push({ index: m.index, kind: /^(until|till|through|thru)$/i.test(m[1]) ? 'until' : 'back' });

  let pick = null;
  for (const d of dates) {
    const k = keywords.filter((x) => x.index < d.index && d.index - x.index <= 60).pop();
    if (k) {
      pick = { iso: k.kind === 'until' ? addDaysIso(d.iso, 1) : d.iso, basis: k.kind === 'until' ? 'until-date-plus-1' : 'return-date' };
      break;
    }
  }
  if (!pick) {
    const latest = dates.reduce((a, b) => (isoToMs(b.iso) > isoToMs(a.iso) ? b : a));
    pick = { iso: latest.iso, basis: 'latest-date-mentioned' };
  }

  const delta = (isoToMs(pick.iso) - refMs) / DAY_MS;
  if (delta < -1 || delta > 180) return null; // implausible: ignore and fall back to the default pause
  return { returnDate: pick.iso, basis: pick.basis };
}

const NUMBER_WORDS = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, few: 3, 'a few': 3, couple: 2, 'a couple': 2, 'a couple of': 2, 'couple of': 2 };

/** @returns {number|null} days to wait before following up (1-365) */
function parseSnoozeDays(text, refMs) {
  const t = String(text || '');
  let m = /\bin\s+(\d+|a\s+few|a\s+couple(?:\s+of)?|couple(?:\s+of)?|few|a|an|one|two|three|four|five|six)\s+(day|week|month|quarter|year)s?\b/i.exec(t);
  if (m) {
    const n = /^\d+$/.test(m[1]) ? Number(m[1]) : NUMBER_WORDS[m[1].toLowerCase().replace(/\s+/g, ' ')];
    const unit = { day: 1, week: 7, month: 30, quarter: 90, year: 365 }[m[2].toLowerCase()];
    if (n && unit) return Math.min(365, n * unit);
  }
  m = /\bnext\s+(week|month|quarter|year)\b/i.exec(t);
  if (m) return { week: 7, month: 30, quarter: 90, year: 365 }[m[1].toLowerCase()];

  const ref = new Date(refMs);
  if (/\bafter\s+(?:the\s+)?(?:new\s+year|holidays?)\b/i.test(t)) {
    const year = ref.getUTCMonth() >= 6 ? ref.getUTCFullYear() + 1 : ref.getUTCFullYear();
    const days = Math.ceil((Date.UTC(year, 0, 6) - refMs) / DAY_MS);
    return days >= 1 ? Math.min(365, days) : null;
  }
  m = /\bq([1-4])\b/i.exec(t);
  if (m) {
    const startMonth = (Number(m[1]) - 1) * 3;
    let start = Date.UTC(ref.getUTCFullYear(), startMonth, 1);
    if (start < refMs) start = Date.UTC(ref.getUTCFullYear() + 1, startMonth, 1);
    return Math.min(365, Math.ceil((start - refMs) / DAY_MS) + 7);
  }
  return null;
}

const NAME_STOPWORDS = new Set(['me', 'us', 'our', 'the', 'my', 'i', 'please', 'thanks', 'thank', 'best', 'regards', 'hi', 'hello', 'sales', 'team', 'support', 'info', 'customer', 'them', 'him', 'her', 'you', 'this', 'that', 'a', 'an']);
const TITLE_RE = /\b(Chief [A-Z][a-z]+ Officer|CEO|CTO|CFO|COO|CMO|CRO|CIO|(?:Vice President|VP|SVP|EVP)(?: of| for)?(?: [A-Z][A-Za-z&]+){0,3}|(?:Head|Director|Manager|Lead|Owner|Founder|Co-?founder|President|Partner|Principal|Controller)(?: of| for)?(?: [A-Z][A-Za-z&]+){0,3})\b/;

function nameFromEmail(email) {
  const local = String(email).split('@')[0];
  if (!/^[a-z]+[._-][a-z]+$/i.test(local)) return '';
  return local.split(/[._-]/).map((p) => p[0].toUpperCase() + p.slice(1).toLowerCase()).join(' ');
}

/**
 * @param {string} text           cleaned reply text (original casing)
 * @param {string} senderEmail    the person who replied (excluded from results)
 * @param {string[]} ownDomains   your own sending domains (excluded from results)
 * @returns {{ email, name, title, confidence, nameFromEmail } | null}
 */
function extractReferral(text, senderEmail, ownDomains) {
  const t = String(text || '');
  const sender = String(senderEmail || '').toLowerCase();
  const own = (ownDomains || []).map((d) => d.toLowerCase());

  const emails = (t.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
    .map((e) => e.toLowerCase())
    .filter((e) => e !== sender && !own.includes(e.split('@')[1]) && !/^(?:noreply|no-reply|donotreply)@/.test(e));
  const email = emails[0] || '';

  let name = '';
  const nameRe = /(?:[Cc]ontact|[Rr]each out to|[Ss]peak (?:with|to)|[Tt]alk to|[Ee]mail|[Tt]ry|forwarded (?:this |it |your \w+ )?to|[Cc]c'?d|[Ll]ooping in|[Ll]oop in|[Dd]irect (?:this )?to|[Ii]ntroduce you to|[Cc]onnect you (?:with|to))\s+((?:Dr\.? |Mr\.? |Ms\.? |Mrs\.? )?[A-Z][a-zA-Z'’-]+(?:\s+[A-Z][a-zA-Z'’-]+){0,2})/;
  const nm = nameRe.exec(t);
  if (nm && !NAME_STOPWORDS.has(nm[1].split(/\s+/)[0].toLowerCase())) name = nm[1].trim();

  let derived = false;
  if (!name && email) {
    name = nameFromEmail(email);
    derived = Boolean(name);
  }

  const tm = TITLE_RE.exec(t);
  const title = tm ? tm[1].trim() : '';

  if (!email && !name) return null;
  return { email, name, title, nameFromEmail: derived, confidence: email ? (name && !derived ? 0.9 : 0.75) : 0.5 };
}

// ---- src/slack-blocks.js ----
/**
 * Slack Block Kit builders (incoming-webhook payloads). Contact emails are masked and reply excerpts are
 * short; set SLACK_INCLUDE_EXCERPT=false to omit excerpts entirely.
 * Preview any payload in https://app.slack.com/block-kit-builder
 */


const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const KINDS = {
  INTERESTED: { icon: '🔥', title: 'Interested reply - follow up now' },
  REVIEW: { icon: '🧐', title: 'Reply needs human review' },
  WRONG_PERSON: { icon: '🔀', title: 'Wrong person - referral found' },
  UNSUBSCRIBE_NO_TARGET: { icon: '🛑', title: 'Opt-out received - ACTION REQUIRED' },
  UNSUBSCRIBE_FYI: { icon: '✅', title: 'Opt-out processed' },
  NOT_NOW_FYI: { icon: '🕐', title: 'Not now - follow-up scheduled' },
  RESUME_REMINDER: { icon: '⏰', title: 'Out-of-office contact is back - re-enroll' },
};

const section = (text) => ({ type: 'section', text: { type: 'mrkdwn', text } });
const context = (text) => ({ type: 'context', elements: [{ type: 'mrkdwn', text }] });

function ownerMention(cfg, ownerId) {
  const id = ownerId ? (cfg.ownerSlackMap || {})[String(ownerId)] : '';
  return id && /^[UW][A-Z0-9]{6,}$/.test(id) ? `<@${id}>` : '';
}

/**
 * @param {string} kind  key of KINDS
 * @param {object} ctx   { reply, classification, decision, cfg, ownerId, hubspotFound, extra }
 */
function buildSlackPayload(kind, ctx) {
  const meta = KINDS[kind] || { icon: 'ℹ️', title: kind };
  const { reply, classification: c, decision, cfg } = ctx;
  const prefix = cfg.sandbox ? '[SANDBOX] ' : '';
  const pct = `${Math.round((c.confidence || 0) * 100)}%`;
  const owner = ownerMention(cfg, ctx.ownerId);

  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: `${prefix}${meta.icon} ${meta.title}`, emoji: true } },
    section(
      `*${esc(maskEmail(reply.contact.email || reply.from.email))}*${reply.from.name ? ` (${esc(reply.from.name)})` : ''}\n` +
        `Subject: ${esc(truncate(reply.subject, 120)) || '_(none)_'}`
    ),
    {
      type: 'section',
      fields: [
        { type: 'mrkdwn', text: `*Classified as*\n${esc(c.label)} · ${pct}${c.source === 'llm' ? ' (LLM)' : ''}` },
        { type: 'mrkdwn', text: `*Source*\n${esc(reply.source)}${reply.sequence.name ? ` · ${esc(reply.sequence.name)}` : ''}` },
      ].concat(owner ? [{ type: 'mrkdwn', text: `*Owner*\n${owner}` }] : []),
    },
  ];

  if (kind === 'REVIEW') {
    const why = decision && decision.reason ? decision.reason : 'below confidence threshold';
    blocks.push(section(`*Why review:* ${esc(why)}\n*Top rule hits:* ${esc((c.matches || []).slice(0, 4).map((m) => m.id).join(', ')) || 'none'}`));
  }
  if (kind === 'WRONG_PERSON') {
    const r = (c.extracted && c.extracted.referral) || null;
    blocks.push(
      section(
        r
          ? `*Referred contact* (best-effort extraction - verify before use)\nName: ${esc(r.name) || '_unknown_'}${r.nameFromEmail ? ' _(guessed from email)_' : ''}\nTitle: ${esc(r.title) || '_unknown_'}\nEmail: ${esc(maskEmail(r.email)) || '_not found_'}`
          : '_No referred contact could be extracted from the reply._'
      )
    );
  }
  if (kind === 'UNSUBSCRIBE_NO_TARGET') {
    blocks.push(section('No suppression target is configured (HubSpot opt-out or `SUPPRESSION_WEBHOOK_URL`). *Suppress this address manually now.*'));
  }
  if (kind === 'RESUME_REMINDER' && ctx.extra && ctx.extra.note) blocks.push(section(esc(ctx.extra.note)));

  if (cfg.slackIncludeExcerpt && c.cleanedText && kind !== 'RESUME_REMINDER') {
    blocks.push(section(`> ${esc(truncate(maskEmailsInText(c.cleanedText).replace(/\s+/g, ' '), 280))}`));
  }
  if (ctx.hubspotFound === false && cfg.hubspotEnabled) blocks.push(context('⚠️ Contact not found in HubSpot - CRM task could not be created.'));
  blocks.push(context(`Reply Triage Router · reply ${esc(reply.replyId)}${cfg.sandbox ? ' · sandbox preview' : ''}`));

  return { text: `${prefix}${meta.title}`, blocks };
}

/** Error-handler payload. Never includes reply content. */
function buildErrorPayload(info) {
  const prefix = info.sandbox ? '[SANDBOX] ' : '';
  return {
    text: `${prefix}Reply Triage Router error in ${info.workflowName}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `${prefix}❌ Workflow error`, emoji: true } },
      section(`*Workflow:* ${esc(info.workflowName)}\n*Node:* ${esc(info.nodeName)}\n*Error:* ${esc(truncate(info.message, 400))}`),
      context(`Execution ${esc(info.executionId || 'n/a')} · a reply may need manual handling`),
    ],
  };
}

// ---- src/router.js ----
/**
 * Routing decision + action planning.
 *
 *   decide()        classification -> route (a label, REVIEW, or BOUNCE)
 *   planActions()   route -> the list of side effects to perform (nothing is executed here)
 *   planResume()    due out-of-office queue items -> resume actions
 *
 * Everything returned is data. The workflow's SANDBOX_MODE gate decides whether any of it is executed.
 */


const MS_PER_HOUR = 3600000;
const MS_PER_DAY = 86400000;

const ROUTES = ['UNSUBSCRIBE', 'INTERESTED', 'OUT_OF_OFFICE', 'WRONG_PERSON', 'NOT_NOW', 'NOT_INTERESTED', 'REVIEW', 'BOUNCE'];

/** Executor outputs of the "Route Action" switch node. */
const ACTION_OUTPUT = {
  HUBSPOT_OPT_OUT: 0,
  SUPPRESSION_WEBHOOK: 1,
  APOLLO_STOP_SEQUENCE: 2,
  SEQUENCE_WEBHOOK: 3,
  HUBSPOT_CREATE_TASK: 4,
  SLACK: 5,
};

function decide(classification, cfg) {
  const { label, confidence } = classification;
  if (label === 'BOUNCE') return { route: 'BOUNCE', reason: 'System sender (bounce / delivery notification)' };
  if (label === 'UNSUBSCRIBE' && confidence >= cfg.unsubscribeThreshold) {
    return { route: 'UNSUBSCRIBE', reason: 'Opt-out honored (threshold is intentionally lower than CONFIDENCE_THRESHOLD)' };
  }
  if (label === 'UNKNOWN') return { route: 'REVIEW', reason: 'No classification rule matched' };
  if (confidence < cfg.confidenceThreshold) {
    return { route: 'REVIEW', reason: `Confidence ${confidence} is below CONFIDENCE_THRESHOLD ${cfg.confidenceThreshold} (best guess: ${label})` };
  }
  return { route: label, reason: `Confidence ${confidence} meets CONFIDENCE_THRESHOLD ${cfg.confidenceThreshold}` };
}

function displayName(reply) {
  return reply.from.name || maskEmail(reply.contact.email || reply.from.email);
}

function planActions(ctx) {
  const { reply, classification: c, decision, cfg, nowMs } = ctx;
  const contact = ctx.contact || {};
  const hubspotId = contact.hubspotContactId || reply.contact.hubspotContactId || '';
  const ownerId = contact.ownerId || '';
  const actions = [];
  const stateOps = [];
  const notes = [];
  const counts = {};

  const add = (kind, request) => {
    counts[kind] = (counts[kind] || 0) + 1;
    actions.push({ id: `${reply.replyId}:${kind}:${counts[kind]}`, kind, route: decision.route, outputIndex: ACTION_OUTPUT[kind], request });
  };

  const slack = (kind, extra) => {
    if (!cfg.slackConfigured && !cfg.sandbox) {
      notes.push(`Slack ${kind} skipped: SLACK_WEBHOOK_URL not set`);
      return;
    }
    add('SLACK', { body: buildSlackPayload(kind, { reply, classification: c, decision, cfg, ownerId, hubspotFound: Boolean(hubspotId), extra }) });
  };

  const task = (subject, body, dueMs, priority) => {
    if (!cfg.hubspotEnabled) return notes.push('CRM task skipped: HUBSPOT_ENABLED=false');
    if (!hubspotId) return notes.push('CRM task skipped: HubSpot contact not found');
    const properties = {
      hs_timestamp: new Date(dueMs).toISOString(),
      hs_task_subject: truncate(subject, 250),
      hs_task_body: truncate(body, 2000),
      hs_task_status: 'NOT_STARTED',
      hs_task_priority: priority,
      hs_task_type: 'TODO',
    };
    if (ownerId) properties.hubspot_owner_id = String(ownerId);
    add('HUBSPOT_CREATE_TASK', {
      body: { properties, associations: [{ to: { id: hubspotId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 204 }] }] },
    });
    return true;
  };

  const pause = (reason, resumeAtIso) => {
    const email = reply.contact.email || reply.from.email;
    if (cfg.sequenceProvider === 'apollo') {
      const cid = reply.contact.apolloContactId;
      const sid = reply.sequence.apolloSequenceId;
      if (!cid || !sid) {
        notes.push('Sequence not paused: payload has no apolloContactId / apolloSequenceId');
        return false;
      }
      add('APOLLO_STOP_SEQUENCE', { body: { contact_ids: [cid], emailer_campaign_ids: [sid], mode: cfg.apolloStopMode, stop_reason: reason } });
      return true;
    }
    if (cfg.sequenceProvider === 'webhook' && cfg.sequenceWebhookConfigured) {
      add('SEQUENCE_WEBHOOK', { body: { action: 'pause', contactEmail: email, sequenceId: reply.sequence.id || null, reason, resumeAt: resumeAtIso || null, replyId: reply.replyId, route: decision.route } });
      return true;
    }
    notes.push('Sequence not paused: SEQUENCE_PROVIDER is "none" (or SEQUENCE_WEBHOOK_URL missing)');
    return false;
  };

  const who = displayName(reply);
  const excerpt = truncate(c.cleanedText.replace(/\s+/g, ' '), 500);
  const taskBody = (extra) => `${extra ? `${extra}\n\n` : ''}Reply (${c.label}, confidence ${Math.round(c.confidence * 100)}%):\n"${excerpt}"\n\nSource: ${reply.source} · reply ${reply.replyId}`;

  switch (decision.route) {
    case 'UNSUBSCRIBE': {
      let targets = 0;
      if (cfg.hubspotEnabled && hubspotId) {
        add('HUBSPOT_OPT_OUT', { contactId: hubspotId, body: { properties: { hs_email_optout: 'true' } } });
        targets++;
      } else if (cfg.hubspotEnabled) {
        notes.push('HubSpot opt-out skipped: contact not found');
      }
      if (cfg.suppressionWebhookConfigured) {
        add('SUPPRESSION_WEBHOOK', { body: { email: reply.contact.email || reply.from.email, reason: 'reply_unsubscribe', replyId: reply.replyId, source: reply.source, receivedAt: reply.receivedAt, confidence: c.confidence, matchedRules: c.matches.map((m) => m.id) } });
        targets++;
      }
      pause('Contact requested removal');
      if (!targets) slack('UNSUBSCRIBE_NO_TARGET');
      else if (cfg.notifyOnUnsubscribe) slack('UNSUBSCRIBE_FYI');
      break;
    }
    case 'INTERESTED':
      pause('Positive reply - handing off to a human');
      task(`Interested reply: follow up with ${who}`, taskBody('Respond quickly - this person replied positively to outbound.'), nowMs + cfg.interestedTaskDueHours * MS_PER_HOUR, 'HIGH');
      slack('INTERESTED');
      break;
    case 'OUT_OF_OFFICE': {
      const rd = c.extracted.returnDate;
      const resumeAt = rd ? `${addDaysIso(rd.returnDate, cfg.oooReenrollDelayDays)}T12:00:00.000Z` : new Date(nowMs + cfg.oooDefaultPauseDays * MS_PER_DAY).toISOString();
      if (pause('Out of office', resumeAt) && cfg.enableLocalResumeQueue) {
        stateOps.push({
          op: 'enqueueResume',
          item: {
            key: reply.replyId,
            resumeAt,
            email: reply.contact.email || reply.from.email,
            name: reply.from.name || '',
            hubspotContactId: hubspotId,
            apolloContactId: reply.contact.apolloContactId,
            apolloSequenceId: reply.sequence.apolloSequenceId,
            sequenceId: reply.sequence.id,
            basis: rd ? rd.basis : 'default-pause',
          },
        });
      }
      break;
    }
    case 'WRONG_PERSON': {
      const r = c.extracted.referral;
      pause('Wrong person');
      const details = r ? `Referred contact (extracted automatically - verify): ${r.name || 'name unknown'}${r.title ? `, ${r.title}` : ''}${r.email ? `, ${r.email}` : ''}` : 'No referred contact could be extracted - read the reply.';
      task(`Enrich referred contact${r && r.name ? `: ${r.name}` : ''} (from ${who})`, taskBody(details), nowMs + MS_PER_DAY, 'MEDIUM');
      slack('WRONG_PERSON');
      break;
    }
    case 'NOT_NOW': {
      const days = c.extracted.snoozeDays || cfg.notNowFollowupDays;
      pause('Not now', new Date(nowMs + days * MS_PER_DAY).toISOString());
      task(`Follow up with ${who} (asked to wait ~${days} days)`, taskBody('Lead said the timing is not right. Re-engage with fresh context.'), nowMs + days * MS_PER_DAY, 'MEDIUM');
      if (cfg.notifyOnNotNow) slack('NOT_NOW_FYI');
      break;
    }
    case 'NOT_INTERESTED':
      pause('Not interested');
      notes.push('No CRM changes: a clear "no" only stops the sequence (it is not an opt-out).');
      break;
    case 'REVIEW':
      if (cfg.pauseOnReview) pause('Held for human review');
      if (cfg.reviewCreateTask) task(`Review reply classification: ${who}`, taskBody(`Router could not classify this confidently. ${decision.reason}`), nowMs + 4 * MS_PER_HOUR, 'MEDIUM');
      slack('REVIEW');
      break;
    case 'BOUNCE':
      notes.push('Ignored: bounces belong in your sending tool, not in reply triage.');
      break;
    default:
      notes.push(`No plan for route "${decision.route}"`);
  }
  return { actions, stateOps, notes };
}

/** HubSpot contact search body: find the contact (and its owner) by email. Read-only. */
function buildContactLookupBody(email) {
  return {
    filterGroups: [{ filters: [{ propertyName: 'email', operator: 'EQ', value: String(email).toLowerCase() }] }],
    properties: ['hubspot_owner_id', 'firstname', 'lastname', 'hs_email_optout'],
    limit: 1,
  };
}

/** Turn due out-of-office queue items into resume actions. */
function planResume(item, cfg, nowMs) {
  const actions = [];
  const make = (kind, request) => actions.push({ id: `${item.key}:RESUME:${kind}`, kind, route: 'RESUME', outputIndex: ACTION_OUTPUT[kind], request });
  const label = item.name || maskEmail(item.email);

  if (cfg.sequenceProvider === 'webhook' && cfg.sequenceWebhookConfigured) {
    make('SEQUENCE_WEBHOOK', { body: { action: 'resume', contactEmail: item.email, sequenceId: item.sequenceId || null, reason: 'Out-of-office return date reached', replyId: item.key } });
  } else if (cfg.hubspotEnabled && item.hubspotContactId) {
    make('HUBSPOT_CREATE_TASK', {
      body: {
        properties: { hs_timestamp: new Date(nowMs).toISOString(), hs_task_subject: truncate(`Re-enroll ${label} in sequence (back from out of office)`, 250), hs_task_body: 'Out-of-office return date has passed. Re-enroll this contact in the sequence.', hs_task_status: 'NOT_STARTED', hs_task_priority: 'MEDIUM', hs_task_type: 'TODO' },
        associations: [{ to: { id: item.hubspotContactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 204 }] }],
      },
    });
  } else if (cfg.slackConfigured || cfg.sandbox) {
    const reply = { replyId: item.key, source: 'resume-queue', from: { email: item.email, name: item.name }, contact: { email: item.email }, sequence: { name: '' }, subject: '' };
    make('SLACK', {
      body: buildSlackPayload('RESUME_REMINDER', { reply, classification: { label: 'OUT_OF_OFFICE', confidence: 1, cleanedText: '', matches: [], extracted: {} }, decision: {}, cfg, extra: { note: `${label} was out of office until about ${item.resumeAt.slice(0, 10)}. Re-enroll them in the sequence.` } }),
    });
  }
  return actions;
}

// ---- node logic (scripts/node-code/wf1-plan.js) ----
// Code node: "Plan Actions" (Run Once for All Items)
// Builds the list of side effects for this reply. Nothing is executed here - the Sandbox gate decides that later.
const d = $input.first().json;
const plan = planActions({
  reply: d.reply,
  classification: d.classification,
  decision: d.decision,
  cfg: d.cfg,
  nowMs: Date.now(),
  contact: d.contact,
});

return [{
  json: {
    sandbox: d.cfg.sandbox,
    replyId: d.reply.replyId,
    plan,
    response: {
      status: 'accepted',
      sandbox: d.cfg.sandbox,
      replyId: d.reply.replyId,
      label: d.classification.label,
